INSERT INTO noticias (titulo, contenido, fecha, imagen, autor, likes) VALUES
('La Azohía, un tesoro del litoral murciano que debemos proteger', 'La Azohía es una pequeña localidad costera del municipio de Cartagena, conocida por sus aguas cristalinas, sus fondos marinos de gran biodiversidad y su encantador palmeral histórico declarado Bien de Interés Cultural.\n\nSin embargo, este paraíso natural se enfrenta a una amenaza creciente: la presión urbanística y la contaminación marina están poniendo en peligro un ecosistema único en el Mediterráneo. Desde SOS La Azohía llevamos años trabajando para que las administraciones tomen medidas urgentes y efectivas.\n\nUnirse a nuestra causa es fácil: puedes firmar nuestra petición, colaborar económicamente o simplemente difundir nuestro mensaje. Juntos podemos salvar La Azohía.', '2025-12-01', '2025-12-23-11-19-10-imagenazohia.jpg', 'Carlos', 0),
('Jornada de limpieza de playas: más de 80 voluntarios en acción', 'El pasado sábado celebramos una nueva jornada de limpieza en las playas de La Azohía y zonas adyacentes. Más de 80 voluntarios se dieron cita desde las 9 de la mañana para recoger residuos plásticos, colillas y otros desechos que habían llegado a la orilla con el temporal de la semana anterior.\n\nEn total se recogieron más de 200 kg de basura, entre los que destacaron redes de pesca abandonadas, envases de plástico y restos de embarcaciones. El resultado fue emocionante: la playa quedó limpia y reluciente, y los asistentes se marcharon con una sonrisa.\n\nDesde SOS La Azohía queremos dar las gracias a todos los voluntarios, a las asociaciones colaboradoras y al Ayuntamiento de Cartagena por el apoyo logístico. ¡Hasta la próxima!', '2025-12-15', 'limpieza.jpg', 'Carlos', 0),
('El palmeral de La Azohía, historia viva del mediterráneo', 'El palmeral de La Azohía es uno de los espacios naturales más singulares del litoral murciano. Con más de 200 palmeras datileras centenarias, este bosque costero constituye un ecosistema único que alberga una importante biodiversidad, tanto en su interior como en la franja litoral adyacente.\n\nDeclarado Bien de Interés Cultural, el palmeral es además un testigo histórico de la presencia árabe en estas tierras, cuyas raíces se hunden en la historia medieval de la región de Murcia. Su conservación no es solo un deber ambiental, sino también un compromiso con nuestra identidad cultural.\n\nSOS La Azohía lleva años reivindicando una mayor protección y puesta en valor de este espacio singular. Puedes visitarlo todos los días del año y disfrutar de uno de los rincones más mágicos del Mediterráneo.', '2025-12-20', 'palmeral.jpg', 'Carlos', 0),
('Nueva campaña: Adopta una palmera y salva el litoral', 'Lanzamos nuestra campaña de concienciación "Adopta una Palmera", con la que cualquier persona o empresa puede asociarse simbólicamente a la conservación del palmeral de La Azohía.\n\nA cambio de una aportación mínima de 20 euros anuales, recibirás un certificado digital de adopción, una fotografía de tu palmera y acceso preferente a nuestras actividades y jornadas de voluntariado.\n\nLas empresas que participen en la campaña podrán incluir el sello "Empresa Comprometida con La Azohía" en su comunicación corporativa. Más de 30 empresas de la región de Murcia ya se han sumado en la primera semana.\n\nPara más información y para adoptar tu palmera, escríbenos a soslaazohia@gmail.com o visita nuestra tienda solidaria.', '2025-12-23', '20251225202345-palmeral.webp', 'Carlos', 0),
('Denuncia: vertidos ilegales amenazan el ecosistema marino', 'SOS La Azohía ha presentado una denuncia formal ante la Consejería de Medio Ambiente de la Región de Murcia y la Capitanía Marítima de Cartagena por la detección de vertidos ilegales en la zona marina protegida de La Azohía.\n\nNuestros voluntarios documentaron el pasado martes la presencia de sustancias contaminantes en el agua a escasos 500 metros de la costa. Las muestras recogidas han sido enviadas a un laboratorio acreditado para su análisis.\n\nExigimos a las autoridades competentes una investigación urgente, la identificación de los responsables y la aplicación de sanciones ejemplares. El mar de La Azohía es un bien común que no podemos permitir que sea destruido por la irresponsabilidad de unos pocos.\n\nSi tienes información sobre estos vertidos o has sido testigo de actividades sospechosas, contáctanos de manera confidencial.', '2025-12-26', '2025-12-23-11-19-10-imagenazohia.jpg', 'Carlos', 0);
